<script setup lang="ts">
import {computed,h,onMounted,onUnmounted,ref} from 'vue';
import {NConfigProvider,NButton,NInput,NInputNumber,NSelect,NSwitch,NTag,NDataTable,NDrawer,NDrawerContent,NFormItem,NAlert,NSpin,NTabs,NTabPane} from 'naive-ui';
import {api,copy,selectDirectory,selectExecutable,desktopMode} from './api';
const theme={common:{primaryColor:'#4f46e5',primaryColorHover:'#6259ee',primaryColorPressed:'#4037cb',borderRadius:'8px',fontFamily:'Inter, Segoe UI, Microsoft YaHei, sans-serif'}};
const pages=[{id:'overview',title:'概览',icon:'◉'},{id:'opencode',title:'OpenCode',icon:'⌘'},{id:'models',title:'模型与别名',icon:'◇'},{id:'keys',title:'访问 Key',icon:'⚿'},{id:'logs',title:'调用日志',icon:'≡'},{id:'statistics',title:'用量统计',icon:'▥'}];
const page=ref('overview'),state=ref<any>(),draft=ref<any>(),models=ref<any[]>([]),busy=ref(false),discovering=ref(false),notice=ref(''),error=ref(''),search=ref(''),statusFilter=ref<string|null>(null),modelFilter=ref<string|null>(null);
const drawer=ref(false),selected=ref<any>(),edit=ref<any>({}),testModel=ref<string|null>(null),testPrompt=ref('你好，请用一句话回复。'),testResult=ref(''),testing=ref(false),details=ref<any>(),detailsOpen=ref(false);
const requestDetail=ref<any>(),loadingDetail=ref(false);
let polling:ReturnType<typeof setInterval>|undefined;
const dirty=computed(()=>draft.value&&state.value&&JSON.stringify(draft.value)!==JSON.stringify(state.value.settings));
const stats=computed(()=>state.value?.statistics??{active:[],rows:[],totals:{},byModel:{},byDay:{}});
const totals=computed(()=>stats.value.totals??{});
const filteredModels=computed(()=>models.value.filter(m=>[m.id,m.target,m.name].some(s=>String(s).toLowerCase().includes(search.value.toLowerCase()))));
const rows=computed(()=>[...stats.value.active,...stats.value.rows].filter((r:any)=>(!modelFilter.value||r.model===modelFilter.value)&&(!statusFilter.value||r.status===statusFilter.value)&&[r.model,r.client,r.id,r.errorCode??''].some(s=>String(s).toLowerCase().includes(search.value.toLowerCase()))));
const number=(n:any)=>Number.isFinite(n)?new Intl.NumberFormat('zh-CN',{maximumFractionDigits:1}).format(n):'—';
const seconds=(n:any)=>Number.isFinite(n)?(n/1000).toFixed(2)+' s':'—';
const time=(value:string)=>new Date(value).toLocaleString('zh-CN',{hour12:false});
const status=(value:string)=>({running:'进行中',completed:'成功',failed:'失败',cancelled:'已取消'}[value]??value);
const tag=(value:string)=>h(NTag,{size:'small',bordered:false,type:value==='completed'?'success':value==='failed'?'error':value==='cancelled'?'warning':'info'},()=>status(value));
const protocolLabel=(p:string)=>({chat:'Chat Completions',responses:'Responses',anthropic:'Anthropic Messages'}[p]??p??'Chat Completions');
const logColumns=[{title:'时间',key:'startedAt',width:158,render:(r:any)=>time(r.startedAt)},{title:'模型 / 客户端',key:'model',minWidth:180,render:(r:any)=>h('div',[h('strong',r.model),h('small',{class:'row-sub'},r.client)])},{title:'协议',key:'protocol',width:150,render:(r:any)=>protocolLabel(r.protocol)},{title:'状态',key:'status',width:90,render:(r:any)=>tag(r.status)},{title:'首字',key:'ttftMs',width:90,render:(r:any)=>seconds(r.ttftMs)},{title:'速度',key:'tokensPerSecond',width:95,render:(r:any)=>Number.isFinite(r.tokensPerSecond)?number(r.tokensPerSecond)+' t/s':'—'},{title:'输入 / 输出',key:'usage',width:140,render:(r:any)=>r.usage?number(r.inputTokens)+' / '+number(r.outputTokens):'未返回'},{title:'总耗时',key:'elapsedMs',width:95,render:(r:any)=>seconds(r.elapsedMs)},{title:'',key:'action',width:58,render:(r:any)=>h(NButton,{text:true,onClick:()=>openDetail(r)},()=> '详情')}];
const modelColumns=[{title:'对外模型名',key:'id',minWidth:200,render:(r:any)=>h('div',[h('strong',r.id),h('small',{class:'row-sub'},r.target)])},{title:'能力',key:'capabilities',width:175,render:(r:any)=>h('div',{class:'tag-row'},[r.toolcall?h(NTag,{size:'small',bordered:false},()=> '工具'):null,r.reasoning?h(NTag,{size:'small',bordered:false,type:'info'},()=> '思考'):null])},{title:'上下文',key:'context',width:110,render:(r:any)=>number(r.context)},{title:'最大输出',key:'output',width:110,render:(r:any)=>number(r.output)},{title:'请求数',key:'usageCount',width:90,render:(r:any)=>number(stats.value.byModel[r.id]?.requests??0)},{title:'',key:'actions',width:120,render:(r:any)=>h(NButton,{size:'small',onClick:()=>openModel(r)},()=> '参数与别名')}];
const aggregateRows=computed(()=>Object.entries(stats.value.byModel).map(([model,s]:[string,any])=>({model,...s})));
const aggregateColumns=[{title:'模型',key:'model',minWidth:210},{title:'请求数',key:'requests',width:90},{title:'成功 / 失败 / 取消',key:'status',width:170,render:(r:any)=>[r.success,r.failed,r.cancelled].join(' / ')},{title:'输入 Token',key:'inputTokens',width:120,render:(r:any)=>number(r.inputTokens)},{title:'输出 Token',key:'outputTokens',width:120,render:(r:any)=>number(r.outputTokens)},{title:'缓存 Token',key:'cachedTokens',width:120,render:(r:any)=>number(r.cachedTokens)},{title:'平均首字',key:'ttft',width:110,render:(r:any)=>r.ttftSamples?seconds(r.ttftSum/r.ttftSamples):'—'},{title:'生成速度',key:'speed',width:110,render:(r:any)=>r.generationMs?number(r.generationTokens/(r.generationMs/1000))+' t/s':'—'}];
const modelOptions=computed(()=>models.value.map(m=>({label:m.id,value:m.id})));
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn();}catch(e:any){error.value=e.message;}finally{busy.value=false;}}
async function loadState(reset=false){const next=await api('/admin/state');state.value=next;if(reset||!draft.value)draft.value=structuredClone(next.settings);}
async function refreshModels(){discovering.value=true;try{models.value=(await api('/admin/models')).models;}finally{discovering.value=false;}}
async function save(){await action(async()=>{const next=await api('/admin/config','POST',draft.value);state.value=next;draft.value=structuredClone(next.settings);notice.value='配置已保存并应用。';await refreshModels();});}
async function toggle(){await action(async()=>{state.value=await api(state.value.running?'/admin/stop':'/admin/start','POST',{});notice.value=state.value.running?'API 服务已启动。':'API 服务已停止。';});}
async function refresh(){await action(async()=>{discovering.value=true;try{models.value=(await api('/admin/refresh','POST',{})).models;notice.value='已重新读取全局 OpenCode 模型。';}finally{discovering.value=false;}});}
function changePage(id:string){page.value=id;search.value='';error.value='';notice.value='';}
async function chooseDirectory(){const value=await selectDirectory();if(value)draft.value.workingDirectory=value;}
async function chooseExecutable(){const value=await selectExecutable();if(value)draft.value.command=[value];}
function generateKey(){return 'ocp_'+Array.from(crypto.getRandomValues(new Uint8Array(24))).map(n=>n.toString(16).padStart(2,'0')).join('');}
function addKey(){draft.value.apiKeys.push({id:crypto.randomUUID(),name:'客户端 '+(draft.value.apiKeys.length+1),key:generateKey(),enabled:true});}
function openModel(model:any){selected.value=model;const original=draft.value.modelOverrides[model.target]??{};edit.value={alias:original.alias??model.id,context:original.context??null,output:original.output??null,temperature:original.defaults?.temperature??null,top_p:original.defaults?.top_p??null,max_tokens:original.defaults?.max_tokens??null,reasoning_effort:original.defaults?.reasoning_effort??null};drawer.value=true;}
function applyModel(){const value:any={defaults:{}};if(edit.value.alias.trim()!==selected.value.id||draft.value.modelOverrides[selected.value.target]?.alias)value.alias=edit.value.alias.trim();for(const k of ['context','output'])if(edit.value[k]!==null)value[k]=edit.value[k];for(const k of ['temperature','top_p','max_tokens','reasoning_effort'])if(edit.value[k]!==null)value.defaults[k]=edit.value[k];draft.value.modelOverrides[selected.value.target]=value;drawer.value=false;notice.value='模型修改已暂存，请点击保存配置。';}
function resetModel(){delete draft.value.modelOverrides[selected.value.target];drawer.value=false;notice.value='已暂存恢复原生模型参数，请保存配置。';}
async function test(){testing.value=true;error.value='';try{const response=await api('/admin/test','POST',{model:testModel.value,prompt:testPrompt.value});testResult.value=response.choices?.[0]?.message?.content??JSON.stringify(response.choices?.[0]?.message);await loadState();}catch(e:any){error.value=e.message;}finally{testing.value=false;}}
async function copyValue(value:string){await action(async()=>{await copy(value);notice.value='已复制到剪贴板。';});}
async function openDetail(row:any){details.value=row;detailsOpen.value=true;requestDetail.value=undefined;loadingDetail.value=true;try{requestDetail.value=await api('/admin/request/'+row.id);}catch(e:any){requestDetail.value={error:e.message};}finally{loadingDetail.value=false;}}
onMounted(async()=>{await action(async()=>{await loadState(true);await refreshModels();});polling=setInterval(()=>{void loadState().catch(()=>{});},2000);});
onUnmounted(()=>clearInterval(polling));
</script>

<template>
<n-config-provider :theme-overrides="theme">
<div class="app-shell">
  <aside class="sidebar">
    <div class="brand"><span class="brand-mark">›_</span><div><strong>OpenCode Proxy</strong><small>本地模型网关</small></div></div>
    <div class="nav-label">工作空间</div>
    <nav><button v-for="item in pages" :key="item.id" :class="{active:page===item.id}" @click="changePage(item.id)"><span class="nav-icon">{{item.icon}}</span>{{item.title}}</button></nav>
    <div class="sidebar-bottom"><span class="status-dot" :class="{online:state?.running}"></span>{{state?.running?'服务运行中':'服务已停止'}}<small>OpenCode Proxy · 0.2.0</small></div>
  </aside>
  <main class="workspace">
    <header class="toolbar"><div class="breadcrumb">工作空间 <span>/</span> <strong>{{pages.find(p=>p.id===page)?.title}}</strong></div><div class="toolbar-actions"><n-tag :type="state?.running?'success':'default'" :bordered="false" round size="small">{{state?.running?'API 在线':'API 离线'}}</n-tag><span class="unsaved" v-if="dirty">有未保存修改</span><n-button :loading="busy" @click="toggle">{{state?.running?'停止服务':'启动服务'}}</n-button><n-button type="primary" :disabled="!dirty" :loading="busy" @click="save">保存配置</n-button></div></header>
    <div class="content">
      <n-alert v-if="error" type="error" :title="error" closable @close="error=''" class="notice"/>
      <n-alert v-if="notice" type="success" :title="notice" closable @close="notice=''" class="notice"/>
      <n-alert v-if="state?.startError" type="warning" title="API 端口无法启动，请在 OpenCode 页面检查监听地址和端口。" class="notice"/>
      <n-alert v-if="stats.storageError" type="warning" title="统计文件保存失败，请检查配置目录的写入权限。" class="notice"/>
      <n-spin :show="!state">
      <template v-if="state && draft">
      <section v-if="page==='overview'">
        <div class="page-heading"><div><p class="eyebrow">CONTROL CENTER</p><h1>一览运行情况</h1><p>连接全局 OpenCode，让模型调用保持可见。</p></div><div class="connection-pill"><span class="status-dot" :class="{online:state.running}"></span>{{state.running?'网关已就绪':'网关未运行'}}</div></div>
        <div class="metrics led-strip"><article class="blk"><span class="k">累计请求</span><strong>{{number(totals.requests??0)}}</strong><small>{{stats.active.length}} 个请求进行中</small></article><article class="blk"><span class="k">Token 用量</span><strong>{{number((totals.inputTokens??0)+(totals.outputTokens??0)+(totals.cachedTokens??0)+(totals.cacheWriteTokens??0))}}</strong><small>输入 {{number(totals.inputTokens??0)}} · 输出 {{number(totals.outputTokens??0)}}</small></article><article class="blk"><span class="k">平均首字</span><strong>{{totals.ttftSamples?seconds(totals.ttftSum/totals.ttftSamples):'—'}}</strong><small>成功流式请求的首个有效内容</small></article><article class="blk"><span class="k">生成速度</span><strong>{{totals.generationMs?number(totals.generationTokens/(totals.generationMs/1000)):'—'}}<em v-if="totals.generationMs"> t/s</em></strong><small>与 Magpie 相同的有效解码窗口</small></article></div>
        <div class="overview-grid"><article class="panel endpoint-panel"><div class="panel-heading"><h2>连接信息</h2><n-tag size="small" :bordered="false">三协议</n-tag></div><label>API Base URL</label><div class="endpoint"><code>{{state.endpoint??'服务未启动'}}</code><n-button text @click="copyValue(state.endpoint??'')" :disabled="!state.endpoint">复制</n-button></div><div class="connection-meta"><div><span>可用模型</span><strong>{{models.length}}</strong></div><div><span>访问 Key</span><strong>{{draft.apiKeys.filter((k:any)=>k.enabled).length}}</strong></div><div><span>并发</span><strong>{{draft.maxConcurrent===0?'不限':draft.maxConcurrent}}</strong></div></div><p class="muted">Chat Completions · Responses · Anthropic Messages 共用模型名和访问 Key。</p></article><article class="panel"><div class="panel-heading"><h2>测试模型</h2><span class="muted">会发起真实调用</span></div><n-select v-model:value="testModel" :options="modelOptions" filterable placeholder="选择模型"/><n-input v-model:value="testPrompt" type="textarea" :autosize="{minRows:2,maxRows:4}" class="test-prompt"/><div class="test-actions"><n-button type="primary" secondary :loading="testing" :disabled="!testModel" @click="test">发送测试</n-button></div><div class="test-result" v-if="testResult">{{testResult}}</div></article></div>
        <article class="panel"><div class="panel-heading"><h2>最近调用</h2><n-button text @click="changePage('logs')">查看全部 →</n-button></div><n-data-table :columns="logColumns" :data="rows.slice(0,8)" :bordered="false" :scroll-x="1040"/></article>
      </section>
      <section v-else-if="page==='opencode'">
        <div class="page-heading"><div><p class="eyebrow">RUNTIME</p><h1>OpenCode 配置</h1><p>复用已安装程序的供应商、登录和认证配置。</p></div></div>
        <article class="panel form-panel"><h2>程序与工作目录</h2><n-form-item label="OpenCode 可执行程序"><div class="field-with-action"><n-input :value="draft.command[0]" @update:value="(v:string)=>draft.command[0]=v" placeholder="opencode 或程序完整路径"/><n-button v-if="desktopMode()" @click="chooseExecutable">选择程序</n-button></div></n-form-item><n-form-item label="附加启动参数（JSON 数组）"><n-input :value="JSON.stringify(draft.command.slice(1))" @blur="(e:any)=>{try{draft.command=[draft.command[0],...JSON.parse(e.target.value)]}catch{error='附加参数必须是 JSON 字符串数组。'}}" placeholder='[]'/></n-form-item><n-form-item label="工作目录"><div class="field-with-action"><n-input v-model:value="draft.workingDirectory" placeholder="留空时为每个请求创建临时目录"/><n-button v-if="desktopMode()" @click="chooseDirectory">选择目录</n-button></div></n-form-item><p class="muted">这里只修改反代工具配置，不改写全局 OpenCode 的供应商与凭证文件。</p></article>
        <article class="panel form-panel"><h2>监听与时限</h2><div class="form-grid"><n-form-item label="API 监听地址"><n-input v-model:value="draft.host"/></n-form-item><n-form-item label="API 端口"><n-input-number v-model:value="draft.port" :min="1" :max="65535"/></n-form-item><n-form-item label="首个输出时限（毫秒）"><n-input-number v-model:value="draft.firstOutputTimeoutMs" :min="1" placeholder="120000"/></n-form-item><n-form-item label="输出空闲时限（毫秒）"><n-input-number v-model:value="draft.idleTimeoutMs" :min="1" placeholder="180000"/></n-form-item><n-form-item label="总时限（0 表示不限）"><n-input-number v-model:value="draft.timeoutMs" :min="0"/></n-form-item><n-form-item label="最大并发（0 表示不限）"><n-input-number v-model:value="draft.maxConcurrent" :min="0"/></n-form-item></div><div class="switch-line"><div><strong>复用空闲 OpenCode 进程</strong><small>每个活动请求仍使用独立进程。</small></div><n-switch v-model:value="draft.workerReuse"/></div><p class="muted">修改监听地址或端口后，服务会重新监听；该过程会中断原监听上的活动连接。</p></article>
        <article class="panel"><h2>配置文件</h2><code class="config-path">{{state.configFile}}</code></article>
      </section>
      <section v-else-if="page==='models'">
        <div class="page-heading"><div><p class="eyebrow">MODEL CATALOG</p><h1>模型与别名</h1><p>自动读取全局 OpenCode，按模型调整对外名称和默认参数。</p></div><n-button :loading="discovering" @click="refresh">刷新模型</n-button></div><article class="panel"><div class="table-tools"><n-input v-model:value="search" clearable placeholder="搜索模型名称或供应商" class="search"/><span class="muted">{{filteredModels.length}} 个模型</span></div><n-data-table :columns="modelColumns" :data="filteredModels" :bordered="false" :scroll-x="880" :pagination="{pageSize:12}"/></article>
      </section>
      <section v-else-if="page==='keys'">
        <div class="page-heading"><div><p class="eyebrow">ACCESS</p><h1>访问 Key</h1><p>用于客户端访问反代 API，与供应商登录凭证分开管理。</p></div><n-button @click="addKey">＋ 新建 Key</n-button></div><article v-for="(key,index) in draft.apiKeys" :key="key.id" class="panel key-panel"><div class="key-title"><n-input v-model:value="key.name" placeholder="客户端名称"/><n-switch v-model:value="key.enabled"/></div><div class="field-with-action"><n-input v-model:value="key.key" type="password" show-password-on="click" placeholder="客户端访问 Key"/><n-button @click="copyValue(key.key)">复制</n-button><n-button @click="key.key=generateKey()">重新生成</n-button><n-button type="error" secondary :disabled="draft.apiKeys.length===1" @click="draft.apiKeys.splice(index,1)">移除</n-button></div><small class="muted">{{key.enabled?'启用':'停用'}} · 修改后点击保存配置</small></article>
      </section>
      <section v-else-if="page==='logs'">
        <div class="page-heading"><div><p class="eyebrow">REQUESTS</p><h1>调用日志</h1><p>保留最近 250 条明细；累计统计会持续保存。</p></div><span class="live-indicator">● 每 2 秒更新</span></div><article class="panel"><div class="table-tools filters"><n-input v-model:value="search" clearable placeholder="搜索模型、客户端或请求 ID"/><n-select v-model:value="modelFilter" :options="modelOptions" filterable clearable placeholder="全部模型"/><n-select v-model:value="statusFilter" :options="[{label:'成功',value:'completed'},{label:'失败',value:'failed'},{label:'已取消',value:'cancelled'},{label:'进行中',value:'running'}]" clearable placeholder="全部状态"/></div><n-data-table :columns="logColumns" :data="rows" :bordered="false" :scroll-x="1040" :pagination="{pageSize:15}"/></article>
      </section>
      <section v-else-if="page==='statistics'">
        <div class="page-heading"><div><p class="eyebrow">USAGE</p><h1>模型使用情况</h1><p>用量来自 OpenCode 实际返回；缺失时不估算、不补零。</p></div></div><div class="metrics led-strip"><article class="blk"><span class="k">成功请求</span><strong>{{number(totals.success??0)}}</strong><small>失败 {{number(totals.failed??0)}} · 其中取消 {{number(totals.cancelled??0)}}</small></article><article class="blk"><span class="k">输入 Token</span><strong>{{number(totals.inputTokens??0)}}</strong><small>{{number(totals.usageSamples??0)}} 次调用返回了用量</small></article><article class="blk"><span class="k">输出 Token</span><strong>{{number(totals.outputTokens??0)}}</strong><small>其中思考 {{number(totals.reasoningTokens??0)}}</small></article><article class="blk"><span class="k">缓存命中 Token</span><strong>{{number(totals.cachedTokens??0)}}</strong><small>与普通输入分开统计，避免重复累加</small></article></div><article class="panel"><div class="panel-heading"><h2>按模型统计</h2><span class="muted">首字与速度只统计成功的流式调用</span></div><n-data-table :columns="aggregateColumns" :data="aggregateRows" :bordered="false" :scroll-x="1170" :pagination="{pageSize:12}"/></article><article class="panel"><h2>最近 14 天</h2><div class="daily-chart"><div v-for="[day,item] in Object.entries(stats.byDay).sort().slice(-14)" :key="day" class="day-column"><span>{{(item as any).requests}}</span><div :style="{height:Math.max(4,((item as any).requests/Math.max(1,...Object.values(stats.byDay).map((s:any)=>s.requests)))*100)+'px'}"></div><small>{{day.slice(5)}}</small></div><p v-if="!Object.keys(stats.byDay).length" class="empty-chart">发起首次调用后显示每日统计。</p></div><p class="muted">日期按服务端时区 {{stats.timeZone}} 分组；调用时间按当前客户端时区显示。</p></article>
      </section>
      </template>
      </n-spin>
    </div>
  </main>
</div>
<n-drawer v-model:show="drawer" :width="440"><n-drawer-content title="模型参数与别名" closable><template v-if="selected"><p class="model-target">{{selected.target}}</p><n-form-item label="对外模型名称 / 别名"><n-input v-model:value="edit.alias"/></n-form-item><div class="form-grid"><n-form-item :label="'上下文上限（原生 '+selected.nativeContext+'）'"><n-input-number v-model:value="edit.context" :min="1" :max="selected.nativeContext" placeholder="跟随 OpenCode"/></n-form-item><n-form-item :label="'输出上限（原生 '+selected.nativeOutput+'）'"><n-input-number v-model:value="edit.output" :min="1" :max="selected.nativeOutput" placeholder="跟随 OpenCode"/></n-form-item><n-form-item label="默认 temperature"><n-input-number v-model:value="edit.temperature" :min="0" :max="2" :step="0.1" :disabled="!selected.temperature" placeholder="跟随 OpenCode"/></n-form-item><n-form-item label="默认 top_p"><n-input-number v-model:value="edit.top_p" :min="0" :max="1" :step="0.1" placeholder="跟随 OpenCode"/></n-form-item></div><n-form-item label="默认 max_tokens"><n-input-number v-model:value="edit.max_tokens" :min="1" :max="edit.output??selected.nativeOutput" placeholder="由客户端决定"/></n-form-item><n-form-item label="默认思考强度"><n-select v-model:value="edit.reasoning_effort" :options="selected.reasoningEfforts.map((v:string)=>({label:v,value:v}))" clearable placeholder="跟随 OpenCode / 客户端"/></n-form-item><p class="muted">默认参数仅在客户端未传对应字段时生效。留空保留 OpenCode 原生默认值。</p></template><template #footer><n-button @click="resetModel">恢复原生配置</n-button><n-button type="primary" @click="applyModel">暂存修改</n-button></template></n-drawer-content></n-drawer>
<n-drawer v-model:show="detailsOpen" :width="680"><n-drawer-content title="调用详情" closable><template v-if="details"><n-tabs type="line" animated><n-tab-pane name="metrics" tab="指标"><div class="detail-status">{{status(details.status)}}</div><dl class="details"><dt>请求 ID</dt><dd>{{details.id}}</dd><dt>模型 / 上游</dt><dd>{{details.model}}<br>{{details.target??'—'}}</dd><dt>协议 / 接口</dt><dd>{{protocolLabel(details.protocol)}}<br>{{details.endpoint}}</dd><dt>客户端</dt><dd>{{details.client}}</dd><dt>时间</dt><dd>{{time(details.startedAt)}}</dd><dt>首字（成功流式统计）</dt><dd>{{seconds(details.ttftMs)}}</dd><dt>客户端首个输出</dt><dd>{{seconds(details.clientFirstMs)}}</dd><dt>生成速度</dt><dd>{{Number.isFinite(details.tokensPerSecond)?number(details.tokensPerSecond)+' Token/s':'未返回'}}</dd><dt>总耗时</dt><dd>{{seconds(details.elapsedMs)}}</dd><dt>输入 / 输出 Token</dt><dd>{{details.usage?number(details.inputTokens)+' / '+number(details.outputTokens):'未返回'}}</dd><dt>缓存 / 思考 Token</dt><dd>{{details.usage?number(details.usage.prompt_tokens_details?.cached_tokens??0)+' / '+number(details.usage.completion_tokens_details?.reasoning_tokens??0):'未返回'}}</dd><dt>HTTP / 结束原因</dt><dd>{{details.httpStatus??'—'}} / {{details.finishReason??'—'}}</dd><dt>进程复用</dt><dd>{{details.workerReused===undefined?'—':details.workerReused?'是':'否'}}</dd><dt>错误 / 超时类型</dt><dd>{{details.errorCode??'—'}} / {{details.timeoutKind??'—'}}</dd></dl><p class="muted">与 Magpie 相同：非流式请求不计首字与速度；速度排除思考 Token、失败请求和明显批量输出。失败统计包含取消。</p></n-tab-pane><n-tab-pane name="request" tab="客户端请求"><n-spin :show="loadingDetail"><p class="muted">完整提示词、历史消息、工具定义和参数仅保存在本地。Authorization 不记录。</p><n-alert v-if="requestDetail?.error" type="warning" :title="requestDetail.error"/><pre v-else class="request-json">{{JSON.stringify(requestDetail?.requestedBody,null,2)}}</pre></n-spin></n-tab-pane><n-tab-pane name="effective" tab="生效请求"><p class="muted">转换为统一 Chat 格式并应用模型默认参数后的请求。由 OpenCode 接收并执行推理，不代表供应商最终 HTTP 字节。</p><pre class="request-json">{{JSON.stringify(requestDetail?.effectiveBody,null,2)}}</pre></n-tab-pane><n-tab-pane name="response" tab="原始响应"><p class="muted">包含流式文本、思考和工具调用参数，响应按原始字节保存在本地。</p><n-alert v-if="requestDetail?.responseTruncated" type="info" :title="'仅预览前 2 MiB，完整响应在：'+requestDetail.responseFile"/><pre class="request-json">{{requestDetail?.responsePreview??'暂无响应'}}</pre></n-tab-pane></n-tabs></template></n-drawer-content></n-drawer>
</n-config-provider>
</template>
